CREATE TABLE october_compendium_race_week_definitions (week_id DATE PRIMARY KEY, definition JSONB NOT NULL);
CREATE TABLE october_compendium_final_race_paths (
 player_id BIGINT PRIMARY KEY REFERENCES players(discord_id) ON DELETE CASCADE,
 path TEXT NOT NULL CHECK (path IN ('core', 'support')),
 selected_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
 selected_on DATE NOT NULL DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'Europe/Moscow')::date
);
CREATE TABLE october_compendium_final_race_legacy (kind TEXT NOT NULL, payload JSONB NOT NULL, archived_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM compendium_star_race_quest_completions WHERE moscow_date BETWEEN DATE '2026-10-19' AND DATE '2026-10-25') THEN
  RAISE EXCEPTION 'Final-week awards already exist: preserve and reconcile them before switching conditions';
 END IF;
END; $$;
INSERT INTO october_compendium_final_race_legacy (kind, payload)
 SELECT 'definition', to_jsonb(day) FROM october_compendium_challenge_days day WHERE moscow_date >= DATE '2026-10-19';
INSERT INTO october_compendium_final_race_legacy (kind, payload)
 SELECT 'progress', to_jsonb(progress) FROM compendium_star_race_quest_progress progress WHERE moscow_date BETWEEN DATE '2026-10-19' AND DATE '2026-10-25';
INSERT INTO october_compendium_final_race_legacy (kind, payload)
 SELECT 'progress-win', to_jsonb(win) FROM compendium_star_race_quest_progress_wins win WHERE moscow_date BETWEEN DATE '2026-10-19' AND DATE '2026-10-25';
DELETE FROM compendium_star_race_quest_progress_wins WHERE moscow_date BETWEEN DATE '2026-10-19' AND DATE '2026-10-25';
DELETE FROM compendium_star_race_quest_progress WHERE moscow_date BETWEEN DATE '2026-10-19' AND DATE '2026-10-25';
UPDATE october_compendium_verification_requests SET status = 'cancelled', next_attempt_at = NULL, finished_at = NOW(),
 last_error = 'Условия третьей недели обновлены. Выберите путь и проверьте задание заново.'
 WHERE challenge_kind = 'star_race' AND moscow_date BETWEEN DATE '2026-10-19' AND DATE '2026-10-25' AND status IN ('pending', 'exhausted');
CREATE FUNCTION prevent_final_race_path_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP = 'DELETE' AND NOT EXISTS (SELECT 1 FROM players WHERE discord_id = OLD.player_id) THEN RETURN OLD; END IF;
 RAISE EXCEPTION 'The final race path cannot be changed or reset';
END; $$;
CREATE TRIGGER final_race_path_is_permanent BEFORE UPDATE OR DELETE ON october_compendium_final_race_paths
 FOR EACH ROW EXECUTE FUNCTION prevent_final_race_path_change();
CREATE FUNCTION validate_final_race_award() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NEW.moscow_date BETWEEN DATE '2026-10-19' AND DATE '2026-10-25' THEN
  IF NOT EXISTS (SELECT 1 FROM october_compendium_final_race_paths WHERE player_id = NEW.player_id AND selected_on <= NEW.moscow_date) THEN
   RAISE EXCEPTION 'Choose a final race path first; earlier dates cannot be completed';
  END IF;
  IF TG_TABLE_NAME = 'compendium_star_race_quest_completions' THEN
   IF NEW.reward_amount <> (CASE WHEN NEW.moscow_date = DATE '2026-10-25' THEN 5 ELSE 4 END) THEN
    RAISE EXCEPTION 'Unexpected final race reward';
   END IF;
  END IF;
 END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER validate_final_race_completion BEFORE INSERT OR UPDATE ON compendium_star_race_quest_completions
 FOR EACH ROW EXECUTE FUNCTION validate_final_race_award();
CREATE TRIGGER validate_final_race_progress BEFORE INSERT OR UPDATE ON compendium_star_race_quest_progress
 FOR EACH ROW EXECUTE FUNCTION validate_final_race_award();
